import React from 'react';
import { Box, Text } from 'ink';
import { MarkdownDisplay } from '../shared/MarkdownDisplay.js';
import { theme } from '../../semantic-colors.js';

interface GeminiMessageContentProps {
  text: string;
  isPending: boolean;
}

/*
 * Gemini-specific message content renderer.
 * This applies Gemini-specific formatting to model output.
 */
export const GeminiMessageContent: React.FC<GeminiMessageContentProps> = ({
  text,
  isPending,
}) => {
  const prefix = '✦ ';
  const color = isPending ? theme.text.primary : theme.text.accent;

  return (
    <Box flexDirection="row">
      <Text color={color}>{prefix}</Text>
      <Box flexGrow={1}>
        <MarkdownDisplay text={text} isPending={isPending} />
      </Box>
    </Box>
  );
};
</content>
